def _collect_loop_body(by_id: dict[str, Node], entry: str) -> set[str]:
    body: set[str] = set()
    stack = [entry]
    while stack:
        node_id = stack.pop()
        if node_id in body:
            continue
        body.add(node_id)
        stack.extend(by_id[node_id].depends_on)
    return body


